def load_config(defaults: dict, env: dict) -> dict:
    """Return a copy of `defaults` where any env var APP_<KEY> overrides the
    value for key <key> (lowercased), coerced to the type of the default."""
    cfg = dict(defaults)
    prefix = "APP_"
    for env_key, env_val in env.items():
        if env_key.startswith(prefix):
            key = env_key[len(prefix):].lower()
            if key in defaults:
                default_val = defaults[key]
                cfg[key] = _coerce(env_val, type(default_val))
    return cfg


def _coerce(value, target_type):
    """Coerce `value` to `target_type`."""
    if target_type is bool:
        if isinstance(value, str):
            return value.lower() in ("1", "true", "yes", "on")
        return bool(value)
    if target_type is int:
        return int(value)
    if target_type is float:
        return float(value)
    return str(value)

import unittest
from cfg import load_config

class TestLoader(unittest.TestCase):
    def test_override_int(self):
        cfg = load_config({"port": 80, "host": "x"}, {"APP_PORT": "8080"})
        self.assertEqual(cfg["port"], 8080)
        self.assertEqual(cfg["host"], "x")

    def test_override_float(self):
        cfg = load_config({"rate": 1.5}, {"APP_RATE": "2.5"})
        self.assertEqual(cfg["rate"], 2.5)

    def test_override_bool_true(self):
        cfg = load_config({"debug": False}, {"APP_DEBUG": "true"})
        self.assertTrue(cfg["debug"])

    def test_override_bool_false(self):
        cfg = load_config({"debug": True}, {"APP_DEBUG": "false"})
        self.assertFalse(cfg["debug"])

    def test_override_str(self):
        cfg = load_config({"name": "old"}, {"APP_NAME": "new"})
        self.assertEqual(cfg["name"], "new")

    def test_no_override_for_unknown_key(self):
        cfg = load_config({"port": 80}, {"APP_UNKNOWN": "123"})
        self.assertEqual(cfg, {"port": 80})

    def test_no_override_without_prefix(self):
        cfg = load_config({"port": 80}, {"PORT": "8080"})
        self.assertEqual(cfg["port"], 80)

if __name__ == "__main__":
    unittest.main()

